import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Create container
  const root = new Group();

  // Determine aspect ratio from atlas region (512x320)
  const aspect = 512 / 320; // 1.6

  // Plane geometry sized to aspect ratio (height = 1 unit)
  const geometry = new PlaneGeometry(aspect, 1);

  // Basic node material (transparent to allow alpha)
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
    color: 0xffffff,
  });

  // Mesh
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture asynchronously; apply when ready
  let texture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // User data for handlers and cleanup
  root.userData.handlers = {};

  // Store references for cleanup
  const disposables = [];

  // Cleanup function
  root.userData.cleanup = () => {
    // Dispose material and geometry
    material.dispose();
    geometry.dispose();

    // Dispose texture if loaded
    if (texture) texture.dispose();

    // Kill any GSAP timelines (none in this node)
    gsap.globalTimeline.clear();

    // Cleanup any primitive instances (none)
    disposables.forEach((d) => {
      if (d && typeof d.cleanup === 'function') d.cleanup();
    });
  };

  return root;
}
